public partial class Report_ViewNG2Result : System.Web.UI.Page
{
    protected void Page_Load(object sender, EventArgs e)
    {
        try
        {
            int matchID = CastAide.AsInt32(Request.QueryString["matchid"], 0);
            string result = string.Empty;

            if (!Permissions.HasPermission(Enumerations.Functions.AccessSpecialSites))
            {
                this.lResult.Text = "<script type=\"text/javascript\">location.href='../AccessSpecialSiteDenied.aspx';</script>";
            }
            else
            {
                result = new ScoreInformationService().GetNG2Result(matchID);                    
                this.lResult.Text = result;
            }
        }
        catch (Exception exception)
        {
            LogExtensions.ExceptionHandler(exception);
            lResult.Text = exception.Message;
        }
    }
}